{
  "name": "agent-operators",
  "description": "A plugin marketplace for Claude Code operator subagents. Each operator wraps a CLI tool behind a dedicated subagent with enforcement hooks that block direct CLI usage.",
  "author": "htxryan",
  "owner": {
    "name": "htxryan",
    "url": "https://github.com/htxryan"
  },
  "plugins": [
    {
      "name": "operator-system",
      "description": "Base infrastructure for operator subagents. Provides CLI enforcement hooks, subagent lifecycle tracking, the git-operator agent, and a scaffolding skill for creating new operators.",
      "source": "./plugins/operator-system",
      "keywords": ["operators", "subagents", "git", "enforcement", "hooks"]
    },
    {
      "name": "operator-github",
      "description": "GitHub operator subagent. Guards the gh CLI and provides expert GitHub operations (PRs, issues, Actions, releases).",
      "source": "./plugins/operator-github",
      "keywords": ["github", "gh", "pull-requests", "issues", "actions"]
    },
    {
      "name": "operator-bun",
      "description": "Bun runtime and package manager operator subagent. Guards bun and bunx CLI commands.",
      "source": "./plugins/operator-bun",
      "keywords": ["bun", "bunx", "package-manager", "runtime", "testing"]
    },
    {
      "name": "operator-cloudflare-wrangler",
      "description": "Cloudflare Workers operator subagent. Guards the wrangler CLI for deployments, secrets, KV, R2, Queues, and more.",
      "source": "./plugins/operator-cloudflare-wrangler",
      "keywords": ["cloudflare", "wrangler", "workers", "kv", "r2", "queues"]
    },
    {
      "name": "operator-drizzle",
      "description": "Drizzle ORM operator subagent. Guards the drizzle-kit CLI for migrations, schema push/pull, and Drizzle Studio.",
      "source": "./plugins/operator-drizzle",
      "keywords": ["drizzle", "drizzle-kit", "orm", "migrations", "database"]
    },
    {
      "name": "operator-neon",
      "description": "Neon Postgres operator subagent. Guards the neonctl CLI for branch management, connection strings, and database operations.",
      "source": "./plugins/operator-neon",
      "keywords": ["neon", "neonctl", "postgres", "database", "branching"]
    }
  ]
}
